import pdfMake from 'pdfmake/build/pdfmake';
import { customVfs } from '@/utils/customVfs';
import { generateQRCode, formatPrice, epochToDate, formatStringDate } from '@/utils/Helpers';
import type { Content, TDocumentDefinitions, TableCell, ContentStack } from 'pdfmake/interfaces';
import { warnaTema } from "@/utils/tema";

// VFS dan Fonts (Sama seperti file-file sebelumnya)
pdfMake.vfs = customVfs.pdfMake.vfs;
pdfMake.fonts = {
    Arial: {
        normal: "Arial.ttf",
        bold: "Arial_Bold.ttf",
        italics: "Arial_Italic.ttf",
        bolditalics: "Arial_Bold_Italic.ttf",
    },
};

export function dummyLogo() {
    return "data:image/png;base64,";
}

// Fungsi generateSignatureBlock 
async function generateSignatureBlock(title: string, name: string | null, qrText: string, showDate: boolean = false, dateText: string = ''): Promise<ContentStack> {
    let qrCodeDataUrl = '';
    if (name) {
        try {
            qrCodeDataUrl = await generateQRCode(qrText);
        } catch (qrError) {
            console.error("Gagal generate QR Code:", qrError);
        }
    }

    const qrCodeImage: Content = qrCodeDataUrl
        ? { image: qrCodeDataUrl, width: 70, alignment: 'center', margin: [0, 5, 0, 5] }
        : { text: ' ', alignment: 'center', margin: [0, 30, 0, 30] }; // Placeholder

    const stack: Content[] = [];

    if (showDate && dateText) {
        stack.push({ text: dateText, alignment: 'center', fontSize: 9, margin: [0, 0, 0, 10], bold: true });
    }

    stack.push(
        { text: title, bold: true, fontSize: 9, alignment: 'center' },
        qrCodeImage,
        { text: name || '-', bold: true, fontSize: 9, margin: [0, 5, 0, 0], alignment: 'center' },
        { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 120, y2: 0, lineWidth: 0.5, lineColor: '#000' }], margin: [0, 0, 0, 2] }
    );

    return {
        stack: stack,
        alignment: 'center'
    };
}

// Fungsi helper untuk format tanggal Indonesia (contoh: 01 Desember 2025)
const formatIndonesianDate = (epoch: number | string | Date): string => {
    if (!epoch) return '-';
    try {
        let dateValue = Number(epoch);
        if (String(dateValue).length === 10) {
            dateValue *= 1000;
        }

        const date = new Date(dateValue);
        if (isNaN(date.getTime())) return '-';

        return new Intl.DateTimeFormat('id-ID', {
            day: '2-digit',
            month: 'long',
            year: 'numeric'
        }).format(date);
    } catch (e) {
        return '-';
    }
};

// Fungsi formatDate 
const formatDate = (epoch: number | string | Date, format: 'date' | 'dateTime' = 'date'): string => {
    if (!epoch) return '-';
    try {
        const date = new Date(epoch);
        if (isNaN(date.getTime())) {
            const epochNum = parseInt(String(epoch), 10);
            if (isNaN(epochNum)) {
                const stringDate = new Date(String(epoch));
                if (!isNaN(stringDate.getTime())) {
                    if (format === 'date') return stringDate.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' });
                    if (format === 'dateTime') return stringDate.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
                }
                throw new Error("Invalid date string or epoch format");
            }
            if (String(epoch).length === 13) {
                const dateFromMs = new Date(epochNum);
                if (format === 'date') return dateFromMs.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' });
                if (format === 'dateTime') return dateFromMs.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
            }
            const dateFromSec = new Date(epochNum * 1000);
            if (format === 'date') return dateFromSec.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' });
            if (format === 'dateTime') return dateFromSec.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });

            throw new Error("Invalid date object from epoch");
        }
        if (format === 'date') {
            return date.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric' });
        }
        if (format === 'dateTime') {
            return date.toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
        }
        return date.toLocaleDateString('id-ID');
    } catch (e) {
        console.error("Error formatting date:", e);
        try {
            return formatStringDate(String(epoch), format) || '-';
        } catch (error) {
            console.error("Error formatting date as string:", error);
            return '-';
        }
    }
}

/**
 * Generate PDF Pengeluaran Unit (3 Mode)
 */
export const generatePengeluaranUnitPdf = async (data: any, clinicProfileData: any): Promise<string> => {
    const todayStr = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
    const dateText = `Surabaya, ${todayStr}`;
    const mode = data.jenisPengeluaran; // 'pemakaian unit', 'pengeluaran tanpa permintaan', 'pemusnahan barang'

    // --- Info Permintaan (Kiri & Kanan) ---
    const leftStack: Content[] = [
        { columns: [{ text: 'No. Transaksi', width: 90 }, { text: ':', width: 5 }, { text: data.noPengeluaran || '-', bold: true }], margin: [9, 0, 0, 3] },
        { columns: [{ text: 'Jenis Pengeluaran', width: 90 }, { text: ':', width: 5 }, { text: data.jenisPengeluaran || '-', bold: true }], margin: [9, 0, 0, 3] },
        { columns: [{ text: 'Kategori Item', width: 90 }, { text: ':', width: 5 }, { text: data.kategoriItem || '-', bold: true }], margin: [9, 0, 0, 3] },
        { columns: [{ text: 'Jenis Stok', width: 90 }, { text: ':', width: 5 }, { text: data.jenisStok || '-', bold: true }], margin: [9, 0, 0, 3] },
        { columns: [{ text: 'Jenis Item', width: 90 }, { text: ':', width: 5 }, { text: data.jenisItem || '-', bold: true }], margin: [9, 0, 0, 0] },
    ];

    const rightStack: Content[] = [
        { columns: [{ text: 'Tgl. Pengeluaran', width: 90 }, { text: ':', width: 5 }, { text: formatIndonesianDate(data.tanggalPengeluaran), bold: true }], margin: [0, 0, 0, 3] },
        { columns: [{ text: 'Lokasi Gudang', width: 90 }, { text: ':', width: 5 }, { text: data.lokasiStokAwal?.name || '-', bold: true }], margin: [0, 0, 0, 3] },
    ];

    // --- Data Info Dinamis berdasarkan Mode ---
    if (mode === 'pengeluaran tanpa permintaan') {
        rightStack.push({ columns: [{ text: 'Tujuan Permintaan', width: 90 }, { text: ':', width: 5 }, { text: data.lokasiStokAkhir || '-', bold: true }], margin: [0, 0, 0, 3] });
    } else if (mode === 'pemusnahan barang') {
        rightStack.push({ columns: [{ text: 'Jenis Pemusnahan', width: 90 }, { text: ':', width: 5 }, { text: data.jenisPemusnahan || '-', bold: true }], margin: [0, 0, 0, 3] });
    }

    rightStack.push({ columns: [{ text: 'Petugas Pengeluaran', width: 90 }, { text: ':', width: 5 }, { text: data.petugasPengeluaran || '-', bold: true }], margin: [0, 0, 0, 3] });


    // --- Data Item ---
    const itemsArray = Array.isArray(data.items) ? data.items : [];
    const totalItems = data.totalItem || itemsArray.length; // Ambil totalItem dari root jika ada

    // Sesuaikan header tabel berdasarkan Figma
    const tableHeaders: TableCell[] = [
        { text: 'Nama Item', style: 'tableHeader', alignment: 'left' },
        { text: 'Exp. Date', style: 'tableHeader', alignment: 'center' },
        { text: 'Pengeluaran', style: 'tableHeader', alignment: 'center' },
        { text: 'Satuan/Isi', style: 'tableHeader', alignment: 'center' },
        { text: 'Harga Dasar', style: 'tableHeader', alignment: 'right' },
        { text: 'Total (Rp)', style: 'tableHeader', alignment: 'right' },
    ];

    const tableBody = itemsArray.map((item: any) => [
        { text: item.name || '-', style: 'tableCell', alignment: 'left' },
        { text: formatDate(item.expDate, 'date') || '-', style: 'tableCell', alignment: 'center' },
        { text: item.pengeluaran || '0', style: 'tableCell', alignment: 'center' },
        { text: item.satuan || '-', style: 'tableCell', alignment: 'center' },
        { text: formatPrice(item.hargaSatuan) || '0', style: 'tableCell', alignment: 'right' },
        { text: formatPrice(item.total) || '0', style: 'tableCell', alignment: 'right' },
    ]);

    // --- Tanda Tangan (Mode 1 TTD) ---
    const signatures: Content[] = [];
    const signer = {
        title: 'Petugas Pengeluaran',
        name: data.petugasPengeluaran,
        qr: `Pengeluaran ${data.noPengeluaran} oleh: ${data.petugasPengeluaran || '-'} pada ${todayStr}`
    };
    signatures.push({ width: '*', text: '' } as Content); // Spacer kiri
    signatures.push(await generateSignatureBlock(signer.title, signer.name, signer.qr, true, dateText));


    // --- Definisi Dokumen PDF ---
    return new Promise((resolve, reject) => {
        const docDefinition: TDocumentDefinitions = {
            pageSize: 'A4',
            pageMargins: [40, 40, 40, 60],
            defaultStyle: { font: "Arial", fontSize: 9, color: '#333' },
            content: [
                // Header 
                {
                    columns: [
                        { image: dummyLogo(), width: 70, margin: [0, 0, 0, 0] },
                        {
                            stack: [
                                { text: clinicProfileData?.name ?? 'Nama Klinik', bold: true, fontSize: 15, alignment: 'center' },
                                { text: clinicProfileData?.address?.fullAddress ?? 'Alamat Klinik', alignment: 'center', fontSize: 10 },
                                { text: `(${clinicProfileData?.phone ?? '022'}) ${clinicProfileData?.email ?? '-'}`, alignment: 'center', fontSize: 10 },
                            ],
                            margin: [0, 10, 0, 0], width: '*'
                        },
                        { width: 70, text: '' }
                    ],
                    marginBottom: 5,
                },
                // Judul
                {
                    table: {
                        widths: ['*'],
                        body: [[{ text: 'PENGELUARAN', color: 'white', bold: true, fontSize: 16, alignment: 'center', fillColor: warnaTema('300'), border: [false, false, false, false], margin: [0, 6, 0, 6] }]]
                    },
                    layout: 'noBorders', margin: [0, 5, 0, 15]
                },
                //  Info Pengeluaran 
                {
                    columns: [
                        { stack: leftStack, fontSize: 9 },
                        { stack: rightStack, fontSize: 9 }
                    ],
                    marginBottom: 10
                },
                // Divider
                { canvas: [{ type: 'line', x1: 0, y1: 5, x2: 515, y2: 5, lineWidth: 0.5, lineColor: '#D1D5DB' }], margin: [0, 0, 0, 10] },
                // Catatan Awal
                { columns: [{ text: 'Catatan', width: 90 }, { text: ':', width: 5 }, { text: data.catatan || '-', bold: true }], fontSize: 9, marginBottom: 15, marginLeft: 9 },
                // Tabel Item
                {
                    table: {
                        widths: ['*', 'auto', 'auto', 'auto', 'auto', 'auto'],
                        headerRows: 1,
                        body: [tableHeaders, ...tableBody],
                    },
                    layout: {
                        defaultBorder: false,
                        hLineWidth: (i: number, node: any) => (i === 0 || i === 1 || (node && node.table && node.table.body && i === node.table.body.length)) ? 0.5 : 0,
                        vLineWidth: () => 0, // Tidak ada garis vertikal
                        hLineColor: '#E0E0E0',
                        fillColor: (i: number) => (i === 0) ? '#F0F0F0' : null, // Header abu-abu
                        paddingTop: () => 5, paddingBottom: () => 5,
                    },
                    marginBottom: 15
                },
                // 6. Total (Sesuai Figma)
                {
                    columns: [
                        { width: '*', text: '' },
                        {
                            width: '515',
                            table: {
                                widths: ['*', 'auto'], // Kolom label dan nilai
                                body: [
                                    [
                                        { text: 'Total Order', bold: true, fontSize: 9, alignment: 'left' },
                                        { text: `${totalItems} Items`, bold: true, fontSize: 9, alignment: 'right' }
                                    ],
                                    [
                                        { text: 'Grand Total', bold: true, fontSize: 9, alignment: 'left' },
                                        { text: formatPrice(data.totalHarga || 0), bold: true, fontSize: 9, alignment: 'right' }
                                    ]
                                ]
                            },
                            layout: {
                                defaultBorder: false,
                                paddingLeft: () => 5,
                                paddingRight: () => 5,
                                paddingTop: () => 3,
                                paddingBottom: () => 3,
                                fillColor: () => '#EAECEF' // Background abu-abu
                            },
                            marginBottom: 20
                        }
                    ]
                },

                // 7. Tanda Tangan (1 TTD di Kanan)
                {
                    columns: signatures,
                    margin: [0, 30, 0, 0]
                }
            ].filter(Boolean) as Content[],
            styles: {
                tableHeader: { bold: true, fontSize: 9, color: '#333', fillColor: '#F0F0F0', margin: [5, 5, 5, 5] },
                tableCell: { fontSize: 9, margin: [5, 5, 5, 5] }
            }
        };

        // ... (try/catch PDFMake) ...
        try {
            const pdfDoc = pdfMake.createPdf(docDefinition);
            pdfDoc.getBase64((base64) => {
                base64 ? resolve(base64) : reject(new Error("Gagal generate PDF Pengeluaran."));
            });
        } catch (error) {
            console.error("Error PDF Pengeluaran:", error); reject(error);
        }
    });
};